#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <ft2build.h>
#include FT_FREETYPE_H
#include FT_MULTIPLE_MASTERS_H

static void setIntermediateAxis(FT_Face face) {
  if (!FT_HAS_MULTIPLE_MASTERS(face)) return;
  FT_MM_Var* variations = NULL;
  if (FT_Get_MM_Var(face, &variations)) return;
  FT_Fixed* coords = calloc(variations->num_axis ? variations->num_axis : 1, sizeof(FT_Fixed));
  for (unsigned i=0;i<variations->num_axis;i++) coords[i] = (variations->axis[i].minimum + variations->axis[i].def) / 2;
  FT_Set_Var_Design_Coordinates(face, variations->num_axis, coords);
  free(coords); free(variations);
}
int main(int argc,char**argv){
 if(argc<2)return 2; FILE*f=fopen(argv[1],"rb"); if(!f)return 2; fseek(f,0,SEEK_END); long sz=ftell(f); rewind(f); unsigned char*data=malloc(sz); fread(data,1,sz,f); fclose(f);
 FT_Library lib; if(FT_Init_FreeType(&lib)) return 3;
 FT_Face face; if(FT_New_Memory_Face(lib,data,sz,-1,&face)) return 0; long nf=face->num_faces; FT_Done_Face(face);
 for(long fi=0;fi<nf;fi++){
   if(FT_New_Memory_Face(lib,data,sz,-(fi+1),&face)) continue; long ni=face->style_flags>>16; FT_Done_Face(face);
   for(long ii=0;ii<ni+1;ii++){
    if(FT_New_Memory_Face(lib,data,sz,(ii<<16)+fi,&face)) continue;
    FT_Set_Char_Size(face,20*64,20*64,72,72);
    if(ii==0) setIntermediateAxis(face);
    for(unsigned gi=0; gi<(unsigned)face->num_glyphs; gi++) FT_Load_Glyph(face, gi, FT_LOAD_DEFAULT|FT_LOAD_NO_BITMAP);
    FT_Done_Face(face);
   }
 }
 FT_Done_FreeType(lib); free(data); return 0;
}
